const COUNTRY_SRC = {gaza:['ocha','ocha15','ochaPrev','t4p','unosat','unosatOld','rdna','ipc'], lebanon:['ochaLb','t4pLb'], aceh:['bnpb1','bnpb2'], mali:['hnrp','fews']};
/* Review log: the date BIG last checked each country's sources (set by the scheduled review), separate
   from the data date. A check can find no newer data; the data date then stays as published by the source. */
const CHECKED = {gaza:'2026-11-09', lebanon:'2026-11-09', aceh:'2026-11-09', mali:'2026-11-09'};
const SCHED = {gaza:['mingguan','weekly'], lebanon:['dua minggu sekali','every two weeks'], aceh:['bulanan','monthly'], mali:['bulanan','monthly']};
function reviewLine(c){
  const dates = COUNTRY_SRC[c].map(k => SRC[k].date).filter(Boolean).sort();
  const latest = dates[dates.length-1];
  const fd = iso => new Date(iso+'T00:00:00').toLocaleDateString(state.lang==='bm'?'ms-MY':'en-GB',{day:'numeric',month:'short',year:'numeric'});
  const chk = CHECKED[c];
  return `<div class="review">${ico('check', chk ? '#2F7D5B' : '#8A8F93', 1)}
    <span><b>${chk ? x('Disemak','Checked')+' '+fd(chk) : x('Belum disemak oleh semakan berjadual','Not yet checked by the scheduled review')}</b> · ${x('Semakan','Review')} ${L(SCHED[c])}${latest?` · ${x('Data terkini daripada sumber','Latest data from sources')}: ${fd(latest)}`:''}</span>
    ${info(`<p>${x('BIG menyemak sumber rasmi mengikut jadual. Tarikh semakan dan tarikh data adalah berbeza: jika data masih bertarikh lama selepas semakan, sumber belum menerbitkan data yang lebih baharu.','BIG checks official sources on a schedule. The check date and the data date are different: if data is still old after a check, the source has not published anything newer.')}</p><p>${x('Gaza disemak setiap minggu, Lubnan dua minggu sekali, Mali dan Acheh setiap bulan.','Gaza is checked weekly, Lebanon every two weeks, Mali and Aceh monthly.')}</p>`)}</div>`;
}
const TODAY = new Date();
function ageInfo(iso){
  if(!iso) return {cls:'na', txt:x('Tarikh tidak dinyatakan','Date not stated')};
  const m = (TODAY - new Date(iso+'T00:00:00')) / (1000*60*60*24*30.44);
  const cls = m<=2 ? 'ok' : (m<=8 ? 'warn' : 'crit');
  const txt = m<1 ? x(`${Math.max(0,Math.round(m*30.44))} hari lalu`,`${Math.max(0,Math.round(m*30.44))} days ago`) : x(`${Math.round(m)} bulan lalu`,`${Math.round(m)} months ago`);
  return {cls, txt};
}
function srcLine(k){
  const s = SRC[k], a = ageInfo(s.date);
  return `<span>${x('Sumber','Source')}: <a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)}</a></span><span>${x('Data','Data')}: ${s.period[state.lang==='bm'?0:1]}</span><span class="age ${a.cls}">${a.txt}</span>`;
}
const ageChip = k => { const a = ageInfo(SRC[k].date); return `<span class="age ${a.cls}" title="${x('Umur data','Data age')}">${a.txt}</span>`; };
const head = (t,sub,keys) => `<div class="sec-head"><h2>${t}${info((sub?`<p>${sub}</p>`:'')+(keys||[]).map(k=>`<div class="src">${srcLine(k)}</div>`).join(''))}${keys&&keys[0]?ageChip(keys[0]):''}</h2></div>`;

